package org.eclipse.rdf4j.sail.lmdb.bulk;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.EOFException;
import java.io.IOException;
import java.nio.channels.FileChannel;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Properties;

import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class StagedComponentBucketsTest {

	private static final int PARTITION_COUNT = 4;

	@TempDir
	Path temporaryDirectory;

	@Test
	void stagingRoutesEveryComponentInOrderAndRecordsPerPartitionCounts() throws Exception {
		Path target = temporaryDirectory.resolve("staged-store");
		CanonicalStagedInput staged;
		int statements = 200;
		try (BulkLoadWorkspace workspace = openWorkspace(target)) {
			workspace.startPhase(BulkLoadPhase.STAGE_INPUTS);
			try (CanonicalStatementStager stager = stager(workspace.directory())) {
				for (int index = 0; index < statements; index++) {
					stager.writeStatement(statement(index));
				}
				staged = stager.stagedInput();
			}
			workspace.recordStagedInput(staged);
			workspace.completePhase(BulkLoadPhase.STAGE_INPUTS);
		}

		// Every second statement has a context; default-graph statements have no context record.
		assertThat(staged.componentRecords()).isEqualTo(3L * statements + statements / 2);
		Path control = BulkLoadWorkspace.controlDirectory(target);
		assertThat(control.resolve("statements.lz4")).doesNotExist();
		Properties state = BulkLoadWorkspace.inspect(control);
		assertThat(state.getProperty("stage.component-records").split(",")).hasSize(PARTITION_COUNT);
		assertThat(Arrays.stream(state.getProperty("stage.component-records").split(","))
				.mapToLong(Long::parseLong)
				.sum()).isEqualTo(staged.componentRecords());

		long total = 0L;
		for (int partition = 0; partition < PARTITION_COUNT; partition++) {
			List<long[]> records = readPartition(staged, partition);
			assertThat(records).hasSize((int) staged.componentRecords(partition));
			for (int index = 1; index < records.size(); index++) {
				long[] previous = records.get(index - 1);
				long[] current = records.get(index);
				assertThat(current[0] > previous[0] || current[0] == previous[0] && current[1] > previous[1])
						.as("partition %s is ascending by (ordinal, component)", partition)
						.isTrue();
			}
			total += records.size();
		}
		assertThat(total).isEqualTo(staged.componentRecords());
	}

	@Test
	void resumeRejectsATruncatedStagedComponentPartition() throws Exception {
		Path target = temporaryDirectory.resolve("truncated-store");
		CanonicalStagedInput staged;
		try (BulkLoadWorkspace workspace = openWorkspace(target)) {
			workspace.startPhase(BulkLoadPhase.STAGE_INPUTS);
			try (CanonicalStatementStager stager = stager(workspace.directory())) {
				for (int index = 0; index < 50; index++) {
					stager.writeStatement(statement(index));
				}
				staged = stager.stagedInput();
			}
			workspace.recordStagedInput(staged);
			workspace.completePhase(BulkLoadPhase.STAGE_INPUTS);
		}
		Path truncated = null;
		for (int partition = 0; partition < PARTITION_COUNT && truncated == null; partition++) {
			if (staged.componentRecords(partition) > 0L) {
				truncated = staged.componentPath(partition);
			}
		}
		try (FileChannel channel = FileChannel.open(truncated, StandardOpenOption.WRITE)) {
			channel.truncate(channel.size() - 1L);
		}

		try (BulkLoadWorkspace workspace = openWorkspace(target)) {
			assertThatThrownBy(() -> workspace.stagedInput(PARTITION_COUNT))
					.isInstanceOf(IOException.class)
					.hasMessageContaining("staging recorded");
		}
	}

	@Test
	void reclaimsStagedComponentsAfterResolution() throws Exception {
		Path target = temporaryDirectory.resolve("reclaim-store");
		try (BulkLoadWorkspace workspace = openWorkspace(target)) {
			Path components = Files
					.createDirectory(workspace.directory().resolve(StagedComponentBuckets.DIRECTORY_NAME));
			Path runs = Files.createDirectories(workspace.directory().resolve("component-buckets/resolved-runs"));
			Path valueRuns = Files.createDirectories(workspace.directory().resolve("value-component-buckets"));
			Files.writeString(components.resolve("components-00000.lz4"), "staged");

			workspace.reclaimAfterResolution();

			assertThat(components).doesNotExist();
			assertThat(runs).doesNotExist();
			assertThat(valueRuns).doesNotExist();
		}
	}

	@Test
	void restartingIncompletePhasesRemovesTheirPrivateOutputs() throws Exception {
		Path target = temporaryDirectory.resolve("restart-store");
		Path components;
		try (BulkLoadWorkspace workspace = openWorkspace(target)) {
			workspace.startPhase(BulkLoadPhase.STAGE_INPUTS);
			components = Files.createDirectory(workspace.directory().resolve(StagedComponentBuckets.DIRECTORY_NAME));
			Files.writeString(components.resolve("components-00000.lz4"), "partial");
		}
		try (BulkLoadWorkspace workspace = openWorkspace(target)) {
			workspace.startPhase(BulkLoadPhase.STAGE_INPUTS);
			assertThat(components).doesNotExist();
		}

		Path runs;
		try (BulkLoadWorkspace workspace = openWorkspace(target)) {
			workspace.startPhase(BulkLoadPhase.RESOLVE_IDS);
			runs = Files.createDirectories(workspace.directory().resolve("component-buckets/resolved-runs"));
			Files.writeString(runs.resolve("run-00000000000000000000.lz4"), "partial");
		}
		try (BulkLoadWorkspace workspace = openWorkspace(target)) {
			workspace.startPhase(BulkLoadPhase.RESOLVE_IDS);
			assertThat(runs).doesNotExist();
		}
	}

	@Test
	void refusesAWorkspaceCreatedByAnIncompatibleLoaderVersion() throws Exception {
		Path target = temporaryDirectory.resolve("old-version-store");
		try (BulkLoadWorkspace workspace = openWorkspace(target)) {
			workspace.startPhase(BulkLoadPhase.STAGE_INPUTS);
		}
		Path stateFile = BulkLoadWorkspace.controlDirectory(target).resolve("state.properties");
		String state = Files.readString(stateFile);
		Files.writeString(stateFile, state.replaceFirst("(?m)^version=.*$", "version=1"));

		assertThatThrownBy(() -> openWorkspace(target).close())
				.isInstanceOf(IOException.class)
				.hasMessageContaining("incompatible loader version");
	}

	private static List<long[]> readPartition(CanonicalStagedInput staged, int partition) throws IOException {
		List<long[]> records = new ArrayList<>();
		BulkLz4.readConcatenated(staged.componentPath(partition), staged.componentCodec(), input -> {
			while (true) {
				long ordinal;
				try {
					ordinal = input.readLong();
				} catch (EOFException end) {
					return;
				}
				int component = input.readUnsignedByte();
				byte[] key = new byte[input.readInt()];
				input.readFully(key);
				assertThat((int) CanonicalTermCodec.routeHash64(key) & (PARTITION_COUNT - 1)).isEqualTo(partition);
				records.add(new long[] { ordinal, component });
			}
		});
		return records;
	}

	private BulkLoadWorkspace openWorkspace(Path target) throws IOException {
		return BulkLoadWorkspace.open(target, null, ProgressListener.NONE, 1, 1, BulkCompression.FASTEST);
	}

	private CanonicalStatementStager stager(Path directory) throws IOException {
		return new CanonicalStatementStager(directory, new LmdbStoreConfig("spoc,psoc"), PARTITION_COUNT, 16,
				1024 * 1024L, BulkCompression.FASTEST);
	}

	private static Statement statement(int index) {
		var values = SimpleValueFactory.getInstance();
		return values.createStatement(values.createIRI("urn:staged:subject-" + index),
				values.createIRI("urn:staged:predicate-" + index % 3), values.createIRI("urn:staged:object-" + index),
				index % 2 == 0 ? null : values.createIRI("urn:staged:graph-" + index % 5));
	}
}
